function draw() {
  background(0);

  if (gameState !== 'PLAYING') {
    drawEntities();
    return;
  }

  if (keyIsDown(37)) {
    paddle.x -= paddle.speed;
  }
  if (keyIsDown(39)) {
    paddle.x += paddle.speed;
  }

  paddle.x = Math.max(0, Math.min(width - paddle.w, paddle.x));

  if (!ball.active) {
    ball.x = paddle.x + paddle.w / 2;
    ball.y = paddle.y - ball.r;
    ball.timer--;

    if (keyIsDown(32) || ball.timer <= 0) {
      ball.active = true;
      let angle = (rng() - 0.5) * (Math.PI / 2.5);
      let speed = 7;
      ball.vx = speed * Math.sin(angle);
      ball.vy = -speed * Math.cos(angle);
    }
  } else {
    ball.x += ball.vx;
    ball.y += ball.vy;

    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx *= -1;
    } else if (ball.x + ball.r > width) {
      ball.x = width - ball.r;
      ball.vx *= -1;
    }

    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy *= -1;
    }

    if (ball.y + ball.r > height) {
      lives--;
      if (lives <= 0) {
        gameState = 'GAMEOVER';
      } else {
        resetBall();
      }
    }

    if (ball.vy > 0 && ball.y + ball.r >= paddle.y && ball.y - ball.r <= paddle.y + paddle.h) {
      if (ball.x >= paddle.x && ball.x <= paddle.x + paddle.w) {
        ball.y = paddle.y - ball.r;
        let hitPoint = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
        hitPoint = Math.max(-1, Math.min(1, hitPoint));
        let angle = hitPoint * (Math.PI / 3);
        let speed = Math.sqrt(ball.vx * ball.vx + ball.vy * ball.vy);
        ball.vx = speed * Math.sin(angle);
        ball.vy = -speed * Math.cos(angle);
      }
    }

    for (let i = 0; i < bricks.length; i++) {
      let b = bricks[i];
      if (!b.active) continue;

      let testX = ball.x;
      let testY = ball.y;

      if (ball.x < b.x) testX = b.x;
      else if (ball.x > b.x + b.w) testX = b.x + b.w;

      if (ball.y < b.y) testY = b.y;
      else if (ball.y > b.y + b.h) testY = b.y + b.h;

      let distX = ball.x - testX;
      let distY = ball.y - testY;
      let distance = Math.sqrt((distX * distX) + (distY * distY));

      if (distance <= ball.r) {
        b.active = false;
        score += 10;

        for (let p = 0; p < 8; p++) {
          let angle = rng() * Math.PI * 2;
          let speed = 1.5 + rng() * 3.5;
          let life = 15 + rng() * 15;
          particles.push({
            x: b.x + b.w / 2,
            y: b.y + b.h / 2,
            vx: speed * Math.cos(angle),
            vy: speed * Math.sin(angle),
            color: b.color,
            life: life,
            maxLife: life
          });
        }
      }
    }

    if (Math.abs(ball.vy) < 1.5) {
      ball.vy = ball.vy < 0 ? -1.5 : 1.5;
    }
  }

  let allCleared = true;
  for (let i = 0; i < bricks.length; i++) {
    if (bricks[i].active) {
      allCleared = false;
      break;
    }
  }
  if (allCleared && gameState === 'PLAYING') {
    gameState = 'WIN';
  }

  drawEntities();
}
